import { jest } from '@jest/globals';

// Direct import of the mock to test it
import MockOpenAI from '../../src/__mocks__/openai.js';

describe('Direct Mock Test', () => {
  it('should work when imported directly', () => {
    console.log('MockOpenAI:', MockOpenAI);
    console.log('typeof MockOpenAI:', typeof MockOpenAI);
    console.log('MockOpenAI.getMockImplementation:', MockOpenAI.getMockImplementation);
    
    const impl = MockOpenAI.getMockImplementation();
    console.log('Implementation:', impl);
    
    const client = new MockOpenAI({ apiKey: 'test-key' });
    console.log('client from direct import:', client);
    console.log('client keys:', Object.keys(client));
    
    expect(client).toBeDefined();
    expect(client.chat).toBeDefined();
    expect(client.chat.completions).toBeDefined();
    expect(client.chat.completions.create).toBeDefined();
  });
});